function [scenario, egoVehicle] = test()
% createDrivingScenario Returns the drivingScenario defined in the Designer

% Generated by MATLAB(R) 24.1 (R2024a) and Automated Driving Toolbox 24.1 (R2024a).
% Generated on: 05-Sep-2026 20:01:28

% Construct a drivingScenario object.
% scenario = drivingScenario;
scenario = drivingScenario('SampleTime', 0.2);  % 論文のサンプル時間に合わせた

% Add all road segments
roadCenters = [0 0 0;
    1000 0 0];
headings = [0;NaN];
laneSpecifications = [lanespec(2)
    lanespec(1, 'Width', 6)];
lsConnector = laneSpecConnector('Position', 'Right', 'TaperShape', 'None');
compLaneSpecification = compositeLaneSpec(laneSpecifications, 'Connector', lsConnector);
road(scenario, roadCenters, 'Heading', headings, 'Lanes', compLaneSpecification, 'Name', '道路');

% Add the ego vehicle
egoVehicle = vehicle(scenario, ...
    'ClassID', 1, ...
    'Position', [10 1.8 0], ...
    'Mesh', driving.scenario.carMesh, ...
    'Name', '乗用車');

% Add the non-ego actors
vehicle(scenario, ...
    'ClassID', 1, ...
    'Position', [80 1.8 0], ...
    'Mesh', driving.scenario.carMesh, ...
    'Name', '乗用車1');

